    target=root/'dummy.txt'; target.write_text('DUMMY_PRIVATE_SENTINEL_d92af\n')
    from model_tools import handle_function_call
    from hermes_cli.plugins import get_plugin_manager
    manager=get_plugin_manager()
    def deny(**kwargs): return {'action':'block','message':'fixture policy denied'}
    def crash(**kwargs): raise RuntimeError('fixture policy unavailable')
    def malformed(**kwargs): return {'action':'block'}
    for name, hook in [('explicit_block',deny),('callback_exception',crash),('malformed_block_missing_message',malformed)]:
        manager._hooks['pre_tool_call']=[hook]
        result=handle_function_call('read_file',{'path':str(target)},task_id='a',session_id='a')
        print(json.dumps({'probe':name,'sentinel_returned':'DUMMY_PRIVATE_SENTINEL_d92af' in result,'result':json.loads(result)}))
finally: shutil.rmtree(root)
